local ADDON_NAME, ns = ...

-- Terrain padding (build step 5): the real minimap terrain around Blizzard's square minimap, at its
-- exact scale, filling the rest of the map frame when it isn't square (the Height setting). Design:
-- docs/design/terrain-map.md ("Terrain core", "Minimap padding").
--
-- The tiles are the minimap's own ground textures, loaded by FileDataID (Data/Tiles.lua, generated by
-- tools/terrain.py; on Forever a path string doesn't load them). Each continent is a 64 x 64 grid of
-- 533.33-yard tiles: col = 32 - worldY / 533.33, row = 32 - worldX / 533.33, from UnitPosition (world
-- yards; +x north, +y west). So a world point's offset from the player on screen is
-- right = (playerY - y) * scale, up = (x - playerX) * scale, scale in pixels per yard.
--
-- How it's drawn:
--   - A clipping frame of ours over the whole map frame, under Blizzard's minimap (which draws its
--     square on top); a dark fill where there's no terrain (open sea).
--   - Tiles are textures in a fixed pool, one per grid slot: tile (c, r) always lives in slot
--     (c % SLOTS, r % SLOTS), so moving across a tile edge re-textures only the row or column coming in,
--     and SetTexture is skipped when a slot already holds that tile. The visible tiles plus a ring of
--     one around them are kept loaded (the warm ring: a tile is textured before it scrolls into view).
--   - Every frame only positions change: the pixels-per-yard scale (Blizzard's zoom, indoors and out,
--     C_Minimap.GetViewRadius) and the player's position. The set of tiles is worked out again only when
--     the player crosses a tile edge or the scale changes.
--   - Off a continent in the table (instances, unknown maps), or north-up not drawn (Rotate Minimap
--     on: rotated ground is the next part of this step), the padding is just the dark fill.
--   - Nothing at all while the map is square: Blizzard's minimap covers the whole frame then.

local TILE_YARDS = 1600 / 3   -- 533.33
local GRID = 64
local FILL = { 0.05, 0.06, 0.07, 1 }

local Terrain = {
  active = false,
  loaded = 0,   -- SetTexture calls (for /bmap)
  failed = 0,   -- SetTexture calls that returned false
}
ns.Terrain = Terrain

local clip, holder, fill
local slots = {}        -- [slotKey] = texture
local slotTile = {}     -- [slotKey] = tile key it holds
local slotCol, slotRow = {}, {}  -- [texture] = the grid column and row it shows
local lastCol, lastRow, lastMap, lastSpan

local function rotating()
  -- apiguard: allow the argument is a constant string, never a secret value
  return GetCVarBool("rotateMinimap") and not C_Minimap.IsRotateMinimapIgnored()
end

-- Pixels (in `clip`'s units) per yard: Blizzard's minimap shows GetViewRadius yards from its centre to
-- its edge.
local function scale()
  local radius = C_Minimap.GetViewRadius()
  if not radius or radius <= 0 then
    return nil
  end
  local half = Minimap:GetWidth() / 2 * Minimap:GetEffectiveScale() / clip:GetEffectiveScale()
  return half / radius
end

local function slot(c, r, span)
  local key = (c % span) * span + (r % span)
  local t = slots[key]
  if not t then
    t = holder:CreateTexture(nil, "BACKGROUND", nil, 1)
    t:SetSnapToPixelGrid(false)
    t:SetTexelSnappingBias(0)
    slots[key] = t
  end
  return t, key
end

-- Which tiles: every tile the frame shows, plus a ring of one. Re-textures only slots whose tile changed.
local function assign(tiles, col, row, span)
  local half = math.floor(span / 2)
  local used = {}
  for c = col - half, col - half + span - 1 do
    for r = row - half, row - half + span - 1 do
      local t, key = slot(c, r, span)
      used[key] = true
      local tileKey = (c >= 0 and c < GRID and r >= 0 and r < GRID) and (c * GRID + r) or nil
      local fileID = tileKey and tiles[tileKey]
      if slotTile[key] ~= tileKey then
        slotTile[key] = tileKey
        if fileID then
          Terrain.loaded = Terrain.loaded + 1
          if not t:SetTexture(fileID) then
            Terrain.failed = Terrain.failed + 1
          end
        end
      end
      slotCol[t], slotRow[t] = c, r
      t:SetShown(fileID ~= nil)
    end
  end
  for key, t in pairs(slots) do
    if not used[key] then
      t:Hide()
      slotTile[key] = nil
    end
  end
end

local function hideTiles()
  for _, t in pairs(slots) do
    t:Hide()
  end
  wipe(slotTile)
  lastCol, lastRow, lastMap, lastSpan = nil, nil, nil, nil
end

local function update()
  local outer = ns.Minimap.outer
  local square = math.abs(outer:GetWidth() - outer:GetHeight()) < 1
  clip:SetShown(not square)
  if square then
    return
  end
  local px, py, _, mapID = UnitPosition("player")
  local tiles = mapID and ns.Tiles.maps[mapID]
  local s = scale()
  if not (px and py and tiles and s) or rotating() then
    if lastMap then
      hideTiles()
    end
    return
  end

  local tilePixels = TILE_YARDS * s
  -- Enough slots to cover the frame's longer side, plus the ring of one each side (odd, so the
  -- player's tile is the middle one).
  local span = math.ceil(math.max(clip:GetWidth(), clip:GetHeight()) / tilePixels) + 3
  if span % 2 == 0 then
    span = span + 1
  end
  local colF, rowF = 32 - py / TILE_YARDS, 32 - px / TILE_YARDS
  local col, row = math.floor(colF), math.floor(rowF)
  if col ~= lastCol or row ~= lastRow or mapID ~= lastMap or span ~= lastSpan then
    if span ~= lastSpan then
      hideTiles()  -- the slot layout depends on span
    end
    assign(tiles, col, row, span)
    lastCol, lastRow, lastMap, lastSpan = col, row, mapID, span
  end

  -- Positions: tile (c, r)'s top-left corner is at world (x = (32 - r) * T, y = (32 - c) * T).
  for _, t in pairs(slots) do
    if t:IsShown() then
      local left = (slotCol[t] - colF) * tilePixels
      local top = (rowF - slotRow[t]) * tilePixels
      t:SetSize(tilePixels, tilePixels)
      t:ClearAllPoints()
      t:SetPoint("TOPLEFT", holder, "CENTER", left, top)
    end
  end
end

---One line for /bmap.
---@return string
function Terrain:Describe()
  if not self.active then
    return "terrain off"
  end
  local shown = 0
  for _, t in pairs(slots) do
    if t:IsShown() then
      shown = shown + 1
    end
  end
  return ("terrain: %d tiles shown, %d loaded, %d failed (data for build %s)"):format(shown, self.loaded,
    self.failed, ns.Tiles.build)
end

table.insert(ns.Minimap.onActivate, function(outer)
  Terrain.active = true
  clip = CreateFrame("Frame", nil, outer)
  clip:SetAllPoints()
  clip:SetFrameLevel(outer:GetFrameLevel())
  clip:SetClipsChildren(true)
  fill = clip:CreateTexture(nil, "BACKGROUND", nil, 0)
  fill:SetAllPoints()
  fill:SetColorTexture(FILL[1], FILL[2], FILL[3], FILL[4])
  -- The tiles' frame: centred on the minimap (the player), which is centred on `outer`.
  holder = CreateFrame("Frame", nil, clip)
  holder:SetAllPoints()
  clip:SetScript("OnUpdate", update)

  -- The data is for one client build; FileDataIDs rarely change, so a different build only warns.
  local version, buildNumber = GetBuildInfo()
  local running = ("%s.%s"):format(version, buildNumber)
  if running ~= ns.Tiles.build then
    print(("|cffffd100BubbleMap|r: terrain data is for client %s, this is %s; some tiles may be missing.")
      :format(ns.Tiles.build, running))
  end
end)
